mapper.select:
select role
from trip_member
where trip_id = #{tripId}
  and user_id = #{userId}
  and status = 'JOINED'

select status
from trip_member
where trip_id = #{tripId}
  and user_id = #{userId}

select m.trip_id, m.user_id, u.nickname, m.role, m.status
from trip_member m
join users u on m.user_id = u.user_id
where m.trip_id = #{tripId}
  and m.user_id = #{userId}
  and u.del_yn = 'N'

mapper.update:
update trip_member
set role = #{role}
where trip_id = #{tripId}
  and user_id = #{userId}
  and status = 'JOINED'

mapper.delete:
delete from trip_member
where trip_id = #{tripId}
  and user_id = #{userId}

delete from trip_member
where user_id = #{userId}
  and (role is null or role <> 'OWNER')
